function largestArea(grid) {
  const r = grid.length, c = grid[0].length, g = grid.map(x => x.slice()); let best = 0;
  for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) if (g[i][j]) {
    g[i][j] = 0; const st = [[i, j]]; let area = 0;
    while (st.length) { const [a, b] = st.pop(); area++;
      for (const [x, y] of [[a+1,b],[a-1,b],[a,b+1],[a,b-1]]) if (x >= 0 && x < r && y >= 0 && y < c && g[x][y]) { g[x][y] = 0; st.push([x, y]); } }
    best = Math.max(best, area);
  }
  return best;
}
